class Solution:
    def maxItems(self, items: List[List[int]], budget: int) -> int:
        n = len(items)
        cnt = [sum(1 for j in range(n) if j != i and items[j][0] % items[i][0] == 0) for i in range(n)]
        mn = min(p for _, p in items)
        best = 0
        for mask in range(1 << n):
            cost = val = 0
            ok = True
            for i in range(n):
                if mask >> i & 1:
                    cost += items[i][1]
                    if cost > budget:
                        ok = False
                        break
                    val += 1 + cnt[i]
            if ok:
                best = max(best, val + (budget - cost) // mn)
        return best

