class Solution {
public:
    int maxItems(vector<vector<int>>& items, int budget) {
        int n = items.size();
        vector<int> cnt(n, 0);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (i != j && items[j][0] % items[i][0] == 0) cnt[i]++;
        int mn = INT_MAX;
        for (auto& it : items) mn = min(mn, it[1]);
        long long best = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            long long cost = 0, val = 0;
            bool ok = true;
            for (int i = 0; i < n && ok; i++) {
                if (mask >> i & 1) {
                    cost += items[i][1];
                    if (cost > budget) ok = false;
                    else val += 1 + cnt[i];
                }
            }
            if (ok) best = max(best, val + (budget - cost) / mn);
        }
        return (int)best;
    }
};

