class Solution:
    def maxItems(self, items: List[List[int]], budget: int) -> int:
        n = len(items)
        cnt = [0] * n
        for i in range(n):
            fi = items[i][0]
            for j in range(n):
                if i != j and items[j][0] % fi == 0:
                    cnt[i] += 1
        mn = min(p for _, p in items)
        NEG = float('-inf')
        dp = [NEG] * (budget + 1)
        dp[0] = 0
        for i in range(n):
            p, v = items[i][1], 1 + cnt[i]
            for b in range(budget, p - 1, -1):
                if dp[b - p] != NEG:
                    dp[b] = max(dp[b], dp[b - p] + v)
        return max(dp[b] + (budget - b) // mn for b in range(budget + 1) if dp[b] != NEG)

