class Solution {
public:
    int maxItems(vector<vector<int>>& items, int budget) {
        int n = items.size();
        vector<int> cnt(n, 0);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (i != j && items[j][0] % items[i][0] == 0) cnt[i]++;
        int mn = INT_MAX;
        for (auto& it : items) mn = min(mn, it[1]);
        vector<int> dp(budget + 1, INT_MIN);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            int p = items[i][1], v = 1 + cnt[i];
            for (int b = budget; b >= p; b--)
                if (dp[b - p] != INT_MIN)
                    dp[b] = max(dp[b], dp[b - p] + v);
        }
        int best = 0;
        for (int b = 0; b <= budget; b++)
            if (dp[b] != INT_MIN)
                best = max(best, dp[b] + (budget - b) / mn);
        return best;
    }
};

