var maxItems = function(items, budget) {
    const n = items.length;
    const cnt = Array(n).fill(0);
    for (let i = 0; i < n; i++)
        for (let j = 0; j < n; j++)
            if (i !== j && items[j][0] % items[i][0] === 0) cnt[i]++;
    const mn = Math.min(...items.map(it => it[1]));
    const NEG = Number.MIN_SAFE_INTEGER;
    const dp = Array(budget + 1).fill(NEG);
    dp[0] = 0;
    for (const [f, p] of items) {
        let idx = items.findIndex(it => it[0] === f && it[1] === p);
        const v = 1 + cnt[idx];
        for (let b = budget; b >= p; b--)
            if (dp[b - p] !== NEG)
                dp[b] = Math.max(dp[b], dp[b - p] + v);
    }
    let best = 0;
    for (let b = 0; b <= budget; b++)
        if (dp[b] !== NEG)
            best = Math.max(best, dp[b] + Math.floor((budget - b) / mn));
    return best;
};
